-- =============================================================================
-- Dalaran Underbelly -- the 25 NAMED NPCs (real models, not stand-ins)
-- =============================================================================
-- Companion to the DBC additions in the same batch. Retail ships these NPCs as
-- CHARACTER models with an ExtendedDisplayInfo bake and no texture variations,
-- which is the exact shape that renders WHITE if imported naively. Handled per
-- race instead:
--   * stock 3.3.5 races (1-11, goblin included) use the native
--     CreatureDisplayInfoExtra + BakeName path. The character models themselves
--     are untouched -- nothing is retyped, so player characters are unaffected.
--   * worgen (22) and pandaren (24) have no stock ChrRaces entry, so the Extra
--     path cannot work; they use the DC Character\<Race>NPC model copies with the
--     bake bound via TextureVariation_1 and packed NEXT TO THE MODEL, because a
--     MONSTER texture slot never reads from BakedNpcTextures.
--
-- All 25 bakes are already BLP2/DXT with mips at 256x256 or 512x256, i.e.
-- 3.3.5-native -- no re-encode, and none carry the hasMips=2 defect.
--
-- APPLY ORDER: deploy the DBC + texture batch to the client FIRST, then this SQL,
-- then restart the worldserver. A spawn whose display is missing client-side is
-- invisible; a display whose bake is missing renders white.
--
-- Spawn INSERTs are position-guarded, so this cannot duplicate the stand-in pass.
-- =============================================================================

DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 3501100 AND 3501125;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 3501100 AND 3501125;


DELETE FROM `creature` WHERE `guid` BETWEEN 16712000 AND 16712037;
